private void wrapperSearchKeyword(Map<String, Object> data, String keywords) {
        if (StringUtils.isNotEmpty(keywords)) {
            List<Object> logs = (List<Object>) data.get("rows");
            if (logs != null && !logs.isEmpty()) {
                for (Object tLog : logs) {
                    Map<String, Object> log = null;
                    if (tLog instanceof Map) {
                        log = (Map<String, Object>) tLog;
                    } else if (tLog instanceof Log) {
                        log = ((Log) tLog).getAttrs();
                    }
                    if (log != null) {
                        String title = log.get("title").toString();
                        String content = log.get("content").toString();
                        String digest = log.get("digest").toString();
                        log.put("title", ParseUtil.wrapperKeyword(title, keywords));
                        String tryWrapperDigest = ParseUtil.wrapperKeyword(digest, keywords);
                        boolean findInDigest = tryWrapperDigest.length() != digest.length();

                        if (findInDigest) {
                            log.put("digest", tryWrapperDigest);
                        } else {
                            log.put("digest", ParseUtil.wrapperKeyword(ParseUtil.removeHtmlElement(content), keywords));
                        }
                    }
                }
            }
        }

    }

public static List<Map.Entry<Integer, List<String>>> getExecSqlList(String sqlVersion, String basePath) {
        List<Map.Entry<Integer, List<String>>> sqlList = new ArrayList<>();
        Integer version = 0;
        try {
            version = Integer.valueOf(sqlVersion);
        } catch (Exception e) {
            LOGGER.error(e);
        }
        for (File f : getSqlFileList(basePath)) {
            try {
                Integer fileVersion = Integer.valueOf(f.getName().replace(".sql", ""));
                if (fileVersion > version) {
                    LOGGER.info("need update sql " + f);
                    Map.Entry<Integer, List<String>> entry = new AbstractMap.SimpleEntry<>(fileVersion, Arrays.asList(IOUtil.getStringInputStream(new FileInputStream(f)).split("\n")));
                    sqlList.add(entry);
                }
            } catch (FileNotFoundException e) {
                LOGGER.error("", e);
            }
        }
        return sqlList;
    }

public static String getCurrentSqlVersion(String jdbcUrl, String userName, String password, String deriveClass) {
        Connection connect = null;
        try {
            connect = getConnection(jdbcUrl, userName, password, deriveClass);
            if (connect != null) {
                String queryVersionSQL = "select value from website where name = ?";
                try (PreparedStatement ps = connect.prepareStatement(queryVersionSQL)) {
                    ps.setString(1, Constants.ZRLOG_SQL_VERSION_KEY);
                    try (ResultSet resultSet = ps.executeQuery()) {
                        if (resultSet.next()) {
                            return resultSet.getString(1);
                        }
                    }
                }
            }
        } catch (Exception e) {
            LOGGER.error("Not can same deriveClass " + deriveClass, e);
        } finally {
            if (connect != null) {
                try {
                    connect.close();
                } catch (SQLException e) {
                    LOGGER.error(e);
                }
            }
        }
        return "-1";
    }

