private List<String> findKnownHostAlgs(String hostname, int port) {
        for (HostKeyVerifier hkv : hostVerifiers) {
            List<String> keyTypes = hkv.findExistingAlgorithms(hostname, port);
            if (keyTypes != null && !keyTypes.isEmpty()) {
                return keyTypes;
