private ServletFileUpload getServletFileUpload() {
        FileItemFactory factory = new DiskFileItemFactory();
        ServletFileUpload upload = new ServletFileUpload(factory);
        upload.setHeaderEncoding("UTF-8");
        return upload;
    }

private void writeResponse(HttpServletResponse response, String ok) throws IOException {
        response.setContentType("text/html");
        response.getWriter().write(ok);
    }

private FileItem getFileItem(HttpServletRequest request) throws FileUploadException {
        Iterator iterator = getServletFileUpload().parseRequest(request).iterator();
        while (iterator.hasNext()) {
            FileItem item = (FileItem) iterator.next();
            if (!item.isFormField()) {
                return item;
            }
        }
        return null;
    }

private void writeFile(Path path, FileItem uploadedItem) throws IOException {
        if (!ioService.exists(path)) {
            ioService.createFile(path);
        }

        ioService.write(path, IOUtils.toByteArray(uploadedItem.getInputStream()));

        uploadedItem.getInputStream().close();
    }

@Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {

        try {
            if (request.getParameter("path") != null) {
                writeFile(ioService.get(new URI(request.getParameter("path"))), getFileItem(request));

                writeResponse(response, "OK");
            } else if (request.getParameter("folder") != null) {
                writeFile(
                        ioService.get(new URI(request.getParameter("folder") + "/" + request.getParameter("fileName"))),
                        getFileItem(request));

                writeResponse(response, "OK");
            }

        } catch (FileUploadException e) {
            logError(e);
            writeResponse(response, "FAIL");
        } catch (URISyntaxException e) {
            logError(e);
            writeResponse(response, "FAIL");
        }
    }

private void logError(Throwable e) {
        logger.error("Failed to upload a file.", e);
    }

@Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {

        try {

            Path path = ioService.get(new URI(request.getParameter("path")));

            byte[] bytes = ioService.readAllBytes(path);

            response.setHeader("Content-Disposition",
                    String.format("attachment; filename=%s;", path.getFileName().toString()));

            response.setContentType("application/octet-stream");

            response.getOutputStream().write(
                    bytes,
                    0,
                    bytes.length);

        } catch (URISyntaxException e) {
            logger.error("Failed to download a file.", e);
        }

    }

public List<ActivityManager.RunningAppProcessInfo> getRunningAppProcesses() {
        enforceNotIsolatedCaller("getRunningAppProcesses");
        // Lazy instantiation of list
        List<ActivityManager.RunningAppProcessInfo> runList = null;
        final boolean allUsers = ActivityManager.checkUidPermission(INTERACT_ACROSS_USERS_FULL,
                Binder.getCallingUid()) == PackageManager.PERMISSION_GRANTED;
        int userId = UserHandle.getUserId(Binder.getCallingUid());
        synchronized (this) {
            // Iterate across all processes
            for (int i=mLruProcesses.size()-1; i>=0; i--) {
                ProcessRecord app = mLruProcesses.get(i);
                if (!allUsers && app.userId != userId) {
                    continue;
                }
                if ((app.thread != null) && (!app.crashing && !app.notResponding)) {
                    // Generate process state info for running application
                    ActivityManager.RunningAppProcessInfo currApp = 
                        new ActivityManager.RunningAppProcessInfo(app.processName,
                                app.pid, app.getPackageList());
                    fillInProcMemInfo(app, currApp);
                    if (app.adjSource instanceof ProcessRecord) {
                        currApp.importanceReasonPid = ((ProcessRecord)app.adjSource).pid;
                        currApp.importanceReasonImportance =
                                ActivityManager.RunningAppProcessInfo.procStateToImportance(
                                        app.adjSourceProcState);
                    } else if (app.adjSource instanceof ActivityRecord) {
                        ActivityRecord r = (ActivityRecord)app.adjSource;
                        if (r.app != null) currApp.importanceReasonPid = r.app.pid;
                    }
                    if (app.adjTarget instanceof ComponentName) {
                        currApp.importanceReasonComponent = (ComponentName)app.adjTarget;
                    }
                    //Slog.v(TAG, "Proc " + app.processName + ": imp=" + currApp.importance
                    //        + " lru=" + currApp.lru);
                    if (runList == null) {
                        runList = new ArrayList<ActivityManager.RunningAppProcessInfo>();
                    }
                    runList.add(currApp);
                }
            }
        }
        return runList;
    }

private boolean isGetTasksAllowed(String caller, int callingPid, int callingUid) {
        boolean allowed = checkPermission(android.Manifest.permission.REAL_GET_TASKS,
                callingPid, callingUid) == PackageManager.PERMISSION_GRANTED;
        if (!allowed) {
            if (checkPermission(android.Manifest.permission.GET_TASKS,
                    callingPid, callingUid) == PackageManager.PERMISSION_GRANTED) {
                // Temporary compatibility: some existing apps on the system image may
                // still be requesting the old permission and not switched to the new
                // one; if so, we'll still allow them full access.  This means we need
                // to see if they are holding the old permission and are a system app.
                try {
                    if (AppGlobals.getPackageManager().isUidPrivileged(callingUid)) {
                        allowed = true;
                        Slog.w(TAG, caller + ": caller " + callingUid
                                + " is using old GET_TASKS but privileged; allowing");
                    }
                } catch (RemoteException e) {
                }
            }
        }
        if (!allowed) {
            Slog.w(TAG, caller + ": caller " + callingUid
                    + " does not hold GET_TASKS; limiting output");
        }
        return allowed;
    }

public boolean dumpHeap(String process, int userId, boolean managed,
            String path, ParcelFileDescriptor fd) throws RemoteException {

        try {
            synchronized (this) {
                // note: hijacking SET_ACTIVITY_WATCHER, but should be changed to
                // its own permission (same as profileControl).
                if (checkCallingPermission(android.Manifest.permission.SET_ACTIVITY_WATCHER)
                        != PackageManager.PERMISSION_GRANTED) {
                    throw new SecurityException("Requires permission "
                            + android.Manifest.permission.SET_ACTIVITY_WATCHER);
                }

                if (fd == null) {
                    throw new IllegalArgumentException("null fd");
                }

                ProcessRecord proc = findProcessLocked(process, userId, "dumpHeap");
                if (proc == null || proc.thread == null) {
                    throw new IllegalArgumentException("Unknown process: " + process);
                }

                boolean isDebuggable = "1".equals(SystemProperties.get(SYSTEM_DEBUGGABLE, "0"));
                if (!isDebuggable) {
                    if ((proc.info.flags&ApplicationInfo.FLAG_DEBUGGABLE) == 0) {
                        throw new SecurityException("Process not debuggable: " + proc);
                    }
                }

                proc.thread.dumpHeap(managed, path, fd);
                fd = null;
                return true;
            }
        } catch (RemoteException e) {
            throw new IllegalStateException("Process disappeared");
        } finally {
            if (fd != null) {
                try {
                    fd.close();
                } catch (IOException e) {
                }
            }
        }
    }

void cleanupRecentTasksLocked(int userId) {
        if (mRecentTasks == null) {
            // Happens when called from the packagemanager broadcast before boot.
            return;
        }

        final HashMap<ComponentName, ActivityInfo> availActCache = new HashMap<>();
        final HashMap<String, ApplicationInfo> availAppCache = new HashMap<>();
        final IPackageManager pm = AppGlobals.getPackageManager();
        final ActivityInfo dummyAct = new ActivityInfo();
        final ApplicationInfo dummyApp = new ApplicationInfo();

        int N = mRecentTasks.size();

        int[] users = userId == UserHandle.USER_ALL
                ? getUsersLocked() : new int[] { userId };
        for (int user : users) {
            for (int i = 0; i < N; i++) {
                TaskRecord task = mRecentTasks.get(i);
                if (task.userId != user) {
                    // Only look at tasks for the user ID of interest.
                    continue;
                }
                if (task.autoRemoveRecents && task.getTopActivity() == null) {
                    // This situation is broken, and we should just get rid of it now.
                    mRecentTasks.remove(i);
                    task.removedFromRecents();
                    i--;
                    N--;
                    Slog.w(TAG, "Removing auto-remove without activity: " + task);
                    continue;
                }
                // Check whether this activity is currently available.
                if (task.realActivity != null) {
                    ActivityInfo ai = availActCache.get(task.realActivity);
                    if (ai == null) {
                        try {
                            ai = pm.getActivityInfo(task.realActivity,
                                    PackageManager.GET_UNINSTALLED_PACKAGES
                                    | PackageManager.GET_DISABLED_COMPONENTS, user);
                        } catch (RemoteException e) {
                            // Will never happen.
                            continue;
                        }
                        if (ai == null) {
                            ai = dummyAct;
                        }
                        availActCache.put(task.realActivity, ai);
                    }
                    if (ai == dummyAct) {
                        // This could be either because the activity no longer exists, or the
                        // app is temporarily gone.  For the former we want to remove the recents
                        // entry; for the latter we want to mark it as unavailable.
                        ApplicationInfo app = availAppCache.get(task.realActivity.getPackageName());
                        if (app == null) {
                            try {
                                app = pm.getApplicationInfo(task.realActivity.getPackageName(),
                                        PackageManager.GET_UNINSTALLED_PACKAGES
                                        | PackageManager.GET_DISABLED_COMPONENTS, user);
                            } catch (RemoteException e) {
                                // Will never happen.
                                continue;
                            }
                            if (app == null) {
                                app = dummyApp;
                            }
                            availAppCache.put(task.realActivity.getPackageName(), app);
                        }
                        if (app == dummyApp || (app.flags&ApplicationInfo.FLAG_INSTALLED) == 0) {
                            // Doesn't exist any more!  Good-bye.
                            mRecentTasks.remove(i);
                            task.removedFromRecents();
                            i--;
                            N--;
                            Slog.w(TAG, "Removing no longer valid recent: " + task);
                            continue;
                        } else {
                            // Otherwise just not available for now.
                            if (task.isAvailable) {
                                if (DEBUG_RECENTS) Slog.d(TAG, "Making recent unavailable: "
                                        + task);
                            }
                            task.isAvailable = false;
                        }
                    } else {
                        if (!ai.enabled || !ai.applicationInfo.enabled
                                || (ai.applicationInfo.flags&ApplicationInfo.FLAG_INSTALLED) == 0) {
                            if (task.isAvailable) {
                                if (DEBUG_RECENTS) Slog.d(TAG, "Making recent unavailable: "
                                        + task + " (enabled=" + ai.enabled + "/"
                                        + ai.applicationInfo.enabled +  " flags="
                                        + Integer.toHexString(ai.applicationInfo.flags) + ")");
                            }
                            task.isAvailable = false;
                        } else {
                            if (!task.isAvailable) {
                                if (DEBUG_RECENTS) Slog.d(TAG, "Making recent available: "
                                        + task);
                            }
                            task.isAvailable = true;
                        }
                    }
                }
            }
        }

        // Verify the affiliate chain for each task.
        for (int i = 0; i < N; i = processNextAffiliateChainLocked(i)) {
        }

        mTmpRecents.clear();
        // mRecentTasks is now in sorted, affiliated order.
    }

