        String value = null;
        HeaderEntry next = e.next;
        while (next != null) {
            if (next.hash == h && keyEquals(next.key, name)) {
                value = next.value;
                e.next = next.next;
                next.remove();
                --size;
            } else {
                e = next;
            }

            next = e.next;
        }

        e = entries[i];
        if (e.hash == h && keyEquals(e.key, name)) {
            if (value == null) {
                value = e.value;
            }
            entries[i] = e.next;
            e.remove();
            --size;
        }

        return value;
    }

