@Override
    protected XMLReader createReader() throws SAXException {
        if (textConverterRef == null) {
            throw new ProcessException(
                    "No XML fragment wrapper has been assigned to the parser but XML fragment parsers require one");
        }

        // Load the latest TextConverter to get round the issue of the pipeline
        // being cached and therefore holding onto
        // stale TextConverter.

        // TODO: We need to use the cached TextConverter service ideally but
        // before we do it needs to be aware cluster
        // wide when TextConverter has been updated.
        final TextConverter tc = textConverterService.loadByUuid(textConverterRef.getUuid());
        if (tc == null) {
            throw new ProcessException(
                    "TextConverter \"" + textConverterRef.getName() + "\" appears to have been deleted");
        }
        if (!TextConverterType.XML_FRAGMENT.equals(tc.getConverterType())) {
            throw new ProcessException("The assigned text converter is not an XML fragment.");
        }

        // If we are in stepping mode and have made code changes then we want to
        // add them to the newly loaded text
        // converter.
        if (injectedCode != null) {
            tc.setData(injectedCode);
            usePool = false;
        }

        // Get a text converter generated parser from the pool.
        poolItem = parserFactoryPool.borrowObject(tc, usePool);
        final StoredParserFactory storedParserFactory = poolItem.getValue();
        final StoredErrorReceiver storedErrorReceiver = storedParserFactory.getErrorReceiver();
        final ParserFactory parserFactory = storedParserFactory.getParserFactory();

        if (storedErrorReceiver.getTotalErrors() == 0 && parserFactory != null) {
            return parserFactory.getParser();
        } else {
            storedErrorReceiver.replay(new ErrorReceiverIdDecorator(getElementId(), getErrorReceiverProxy()));
        }

        return null;
    }

private void process(final Path in, final Path out) {
        try (final Reader reader = Files.newBufferedReader(in, StreamUtil.DEFAULT_CHARSET);
             final Writer writer = Files.newBufferedWriter(out, StreamUtil.DEFAULT_CHARSET)) {
            final TransformerHandler th = XMLUtil.createTransformerHandler(true);
            th.setResult(new StreamResult(writer));

            SAXParser parser = null;
            try {
                parser = PARSER_FACTORY.newSAXParser();
            } catch (final ParserConfigurationException e) {
                throw ProcessException.wrap(e);
            }

            final SafeXMLFilter filter = new SafeXMLFilter();
            filter.setContentHandler(new XMLFilterContentHandlerAdaptor(th));

            final LocationFactory locationFactory = new DefaultLocationFactory();

            final XMLReader xmlReader = parser.getXMLReader();
            xmlReader.setContentHandler(filter);
            xmlReader.setErrorHandler(new ErrorHandlerAdaptor("XMLReader", locationFactory, new FatalErrorReceiver()));
            xmlReader.parse(new InputSource(reader));

        } catch (final Exception e) {
            System.out.println("Error processing file: " + FileUtil.getCanonicalPath(in));
            e.printStackTrace();
        }
    }

public static void main(final String[] args) throws Exception {
        if (args.length != 2) {
            System.out.println("Bad arguments - provide input and output files.");
        }

        new Sanitiser(Paths.get(args[0]), Paths.get(args[1]));
    }

public long write(final InputStream inputStream, final RASegmentOutputStream segmentOutputStream,
                      final boolean close) {
        long bytesWritten = 0;
        try {
            try {
                bytesWritten = StreamUtil.streamToStream(inputStream, segmentOutputStream, close);
            } finally {
                try {
                    // Ensure all streams are closed.
                    if (segmentOutputStream != null) {
                        segmentOutputStream.flush();
                        if (close) {
                            segmentOutputStream.close();
                        }
                    }

                } finally {
                    if (close && inputStream != null) {
                        inputStream.close();
                    }
                }
            }
            return bytesWritten;
        } catch (final IOException e) {
            throw new UncheckedIOException(e);
        }
    }

public void write(final InputStream inputStream, final RASegmentOutputStream segmentOutputStream) {
        write(inputStream, segmentOutputStream, true);
    }

